// Hand the scorer the lead and its research (the previous node only returned the row).
return [{ json: {
  lead: $('Lead accepted').first().json.lead,
  enrichment: $('Enrich company').first().json,
} }];

// The drafter needs the lead, its research and its score.
return [{ json: {
  lead: $('Lead accepted').first().json.lead,
  enrichment: $('Enrich company').first().json,
  scoring: $('Score lead').first().json,
} }];

// Prepare the approval request and decide how it is handled:
//   auto – an eval lead in demo mode with EVAL_AUTO_APPROVE=true: approved without waiting
//   dry  – DRY_RUN=true: nothing is posted, the Slack message is recorded on the lead instead
//   live – posted to the approval channel; the reviewer decides in the linked n8n form
const lead = $('Lead accepted').first().json.lead;
const enrichment = $('Enrich company').first().json;
const scoring = $('Score lead').first().json;
const draft = $('Draft reply').first().json;
const setting = (key, fallback = '') => String($env[key] ?? fallback);
const on = (key) => setting(key).trim().toLowerCase() === 'true';

const mode = on('DEMO_MODE') && on('EVAL_AUTO_APPROVE') && lead.source === 'eval'
  ? 'auto' : on('DRY_RUN') ? 'dry' : 'live';
const hours = Number(setting('APPROVAL_TIMEOUT_HOURS', '24')) || 24;
const formUrl = $execution.resumeFormUrl;

const clip = (s, n) => (String(s).length > n ? `${String(s).slice(0, n - 1)}…` : String(s));
const slackSafe = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const who = `${lead.name} – ${lead.company || lead.website_domain || 'unknown company'}`;
const criteria = scoring.criteria.map((c) =>
  `• *${c.name}* ${c.rating}/3 (${c.points} of ${c.weight}) – ${slackSafe(c.reason)}`).join('\n');
const profile = enrichment.profile || {};
const facts = [
  ['What they do', profile.what_they_do], ['Industry', profile.industry],
  ['Size', profile.size_estimate], ['Location', profile.location],
].filter(([, f]) => f && f.value !== 'Unknown')
  .map(([label, f]) => `• ${label}: ${slackSafe(f.value)} _(${f.confidence})_`)
  .concat((profile.notable_facts || []).map((f) => `• ${slackSafe(f.fact)} _(${f.confidence})_`))
  .join('\n') || '• Nothing found';
const sources = (enrichment.sources || []).slice(0, 5)
  .map((s) => `<${s.url}|${slackSafe(clip(s.title || s.url, 60))}>`).join(' · ') || 'none';
const tierLabel = `${scoring.score}/100 · ${scoring.tier.toUpperCase()}`;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: clip(`New lead: ${who}`, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: clip(
    `*${tierLabel}*\n${slackSafe(lead.role || 'Role not given')} · ${lead.website_domain || 'no website'}` +
    `${lead.personal_email ? ' · personal email' : ''} · budget: ${slackSafe(lead.budget_range || 'not given')}`, 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: clip(
    `*Their message*\n>${slackSafe(lead.message).replace(/\n/g, '\n>')}`, 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: clip(`*Score breakdown*\n${criteria}`, 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: clip(
    `*Research* (${enrichment.enrichment_status}${enrichment.enrichment_note ? `: ${enrichment.enrichment_note}` : ''})\n${facts}`, 2900) } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: clip(`Sources: ${sources}`, 2900) }] },
  { type: 'section', text: { type: 'mrkdwn', text: clip(
    `*Draft reply* – _${slackSafe(draft.subject)}_\n\`\`\`${slackSafe(draft.body)}\`\`\``, 2900) } },
];
if (draft.flags.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(
    `:warning: *Check before approving*\n${draft.flags.map((f) => `• ${slackSafe(f)}`).join('\n')}`, 2900) } });
}
blocks.push(
  { type: 'actions', elements: [{ type: 'button', style: 'primary', action_id: 'review',
    text: { type: 'plain_text', text: 'Review and decide' }, url: formUrl }] },
  { type: 'context', elements: [{ type: 'mrkdwn', text:
    `Approve, edit or reject in the form. No decision within ${hours} h creates a manual follow-up task.` }] },
);

return [{ json: {
  mode,
  form_url: formUrl,
  timeout_seconds: Math.max(1, Math.round(hours * 3600)),
  message: {
    channel: setting('SLACK_APPROVAL_CHANNEL'),
    text: `New ${scoring.tier} lead: ${who} (${scoring.score}/100). Review: ${formUrl}`,
    blocks,
    unfurl_links: false,
    unfurl_media: false,
  },
} }];

// DRY_RUN: record the Slack message instead of posting it.
const message = $json.message;
return [{ json: { channel: message.channel, ts: `dry-run-${Date.now()}`,
  dry_action: { type: 'slack.chat.postMessage', body: message } } }];

// Slack answers HTTP 200 even on errors; ok=false must stop the lead here.
const reply = $input.first().json;
if (!reply.ok) throw new Error(`Slack rejected the approval request: ${reply.error || 'unknown error'}`);
return [{ json: { channel: reply.channel, ts: reply.ts, dry_action: null } }];

// Turn the reviewer's form answer, the timeout or the eval auto-approval into one decision.
//   approved        – sent as drafted
//   approved_edited – sent with the reviewer's subject/body (any change counts as an edit)
//   rejected        – not sent
//   timeout         – no answer in time: not sent, manual follow-up
const draft = $('Draft reply').first().json;
const request = $('Build approval request').first().json;
const raw = $input.first().json;
// The Wait form returns answers keyed by field label; accept the field name as well.
const answer = {
  decision: raw.decision ?? raw['Decision'],
  reviewer: raw.reviewer ?? raw['Your name'],
  subject: raw.subject ?? raw['Email subject'],
  body: raw.body ?? raw['Email body'],
  reject_reason: raw.reject_reason ?? raw['Reason (only if rejecting)'],
};
const decided_at = new Date().toISOString();
const base = { subject: draft.subject, body: draft.body, reject_reason: '', decided_at };

if (request.mode === 'auto') {
  return [{ json: { ...base, outcome: 'approved', approver: 'eval auto-approve' } }];
}
if (!answer.decision) {
  return [{ json: { ...base, outcome: 'timeout', approver: '' } }];
}
const approver = String(answer.reviewer || '').trim().slice(0, 100) || 'unknown';
const choice = String(answer.decision);
if (choice.startsWith('Reject')) {
  return [{ json: { ...base, outcome: 'rejected', approver,
    reject_reason: String(answer.reject_reason || '').trim().slice(0, 500) || 'No reason given' } }];
}
const subject = String(answer.subject ?? '').replace(/\s+/g, ' ').trim() || draft.subject;
const body = String(answer.body ?? '').replace(/\r\n/g, '\n').trim() || draft.body;
const edited = choice.includes('edits') || subject !== draft.subject || body !== draft.body.trim();
return [{ json: { ...base, subject, body, approver, outcome: edited ? 'approved_edited' : 'approved' } }];

// Prepare the approved email. In DEMO_MODE, mail only goes to DEMO_EMAIL_ALLOWLIST
// (addresses or @domains); anything else is redirected to the first allow-listed address,
// with the real recipient shown in the subject, so a demo can never email a real lead.
const lead = $('Lead accepted').first().json.lead;
const decision = $('Read decision').first().json;
const setting = (key, fallback = '') => String($env[key] ?? fallback).trim();
const demo = setting('DEMO_MODE').toLowerCase() === 'true';
const allowlist = setting('DEMO_EMAIL_ALLOWLIST').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);

let to = lead.email;
let subject = decision.subject;
let redirected_from = null;
if (demo) {
  const allowed = allowlist.some((entry) => entry.startsWith('@')
    ? lead.email.endsWith(entry) : lead.email === entry);
  if (!allowed) {
    const inbox = allowlist.find((entry) => !entry.startsWith('@'));
    if (!inbox) throw new Error('DEMO_MODE is on but DEMO_EMAIL_ALLOWLIST has no address to redirect to');
    redirected_from = lead.email;
    to = inbox;
    subject = `[demo for ${lead.email}] ${subject}`;
  }
}
return [{ json: {
  from: setting('EMAIL_FROM'),
  to,
  subject,
  body: decision.body,
  redirected_from,
} }];

// Everything the CRM step needs, for every path: sent, rejected, timed out or cold.
const seen = (name) => $(name).isExecuted;
const decision = seen('Read decision') ? $('Read decision').first().json : null;
const email = seen('Record email') ? $('Prepare email').first().json : null;
return [{ json: {
  lead: $('Lead accepted').first().json.lead,
  enrichment: $('Enrich company').first().json,
  scoring: $('Score lead').first().json,
  decision,
  email,
  outcome: decision ? decision.outcome : 'cold',
} }];

// Final status, and the Slack update that replaces the approval request with the outcome.
const bundle = $('Bundle for CRM').first().json;
const crm = $input.first().json;
const lead = bundle.lead;
const scoring = bundle.scoring;
const decision = bundle.decision;
const email = bundle.email;
const status = {
  approved: 'approved_sent', approved_edited: 'approved_sent', rejected: 'rejected_by_reviewer',
  timeout: 'needs_manual_follow_up', cold: 'cold_recorded',
}[bundle.outcome];

const slackSafe = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const crmText = crm.dry_run ? 'HubSpot update skipped (dry run)' : 'HubSpot updated';
const sentTo = email ? `email sent to ${email.to}${email.redirected_from ? ` (demo redirect for ${email.redirected_from})` : ''}` : '';
const line = {
  approved: `:white_check_mark: Approved by ${decision?.approver} · ${sentTo} · ${crmText}`,
  approved_edited: `:pencil2: Approved with edits by ${decision?.approver} · ${sentTo} · ${crmText}`,
  rejected: `:x: Rejected by ${decision?.approver}: ${decision?.reject_reason} · no email sent · ${crmText}`,
  timeout: `:hourglass: No decision in time · no email sent · manual follow-up task created · ${crmText}`,
  cold: '',
}[bundle.outcome];

let slack = null;
const rec = $('Record approval request').isExecuted ? $('Record approval request').first().json : null;
const ts = $('Check Slack reply').isExecuted ? $('Check Slack reply').first().json.ts
  : $('Dry-run Slack post').isExecuted ? $('Dry-run Slack post').first().json.ts : null;
const channel = $('Check Slack reply').isExecuted ? $('Check Slack reply').first().json.channel
  : $('Dry-run Slack post').isExecuted ? $('Dry-run Slack post').first().json.channel : null;
if (rec && ts && bundle.outcome !== 'cold') {
  const who = `${lead.name} – ${lead.company || lead.website_domain || 'unknown company'}`;
  slack = {
    channel, ts,
    text: `${who} (${scoring.score}/100 ${scoring.tier.toUpperCase()}): ${line}`,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn',
        text: `*${slackSafe(who)}* · ${scoring.score}/100 ${scoring.tier.toUpperCase()}\n${slackSafe(line)}` } },
      ...(email ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: `Subject: ${slackSafe(email.subject)}` }] }] : []),
    ],
  };
}
return [{ json: {
  lead_id: lead.lead_id, status, outcome: bundle.outcome, slack,
  crm: crm.dry_run ? { dry_run: true } : crm,
  dry_actions: crm.dry_run ? crm.dry_actions : [],
} }];
